def grade_chunk(chunk, query_terms):
    # score each chunk as correct, ambiguous, or incorrect
    overlap = sum(1 for term in query_terms if term in chunk.lower())
    if overlap >= 2:
        return "correct"
    if overlap == 1:
        return "ambiguous"
    return "incorrect"

def web_search_fallback(query):
    # fall back to an external web search
    return f"Simulated web search result for: {query}"

def refine_chunk(chunk, query_terms):
    # refine an ambiguous chunk rather than discard it
    return chunk

def corrective_rag(query, chunks):
    query_terms = query.lower().split()
    grades = [(c, grade_chunk(c, query_terms)) for c in chunks]

    if all(g == "incorrect" for _, g in grades):
        return [web_search_fallback(query)]

    refined = []
    for chunk, grade in grades:
        if grade == "correct":
            refined.append(chunk)
        elif grade == "ambiguous":
            refined.append(refine_chunk(chunk, query_terms))
    return refined

chunks = [
    "The Falcon plan costs twenty dollars per month.",
    "Support hours are weekdays only.",
]
query = "falcon plan cost"

result = corrective_rag(query, chunks)
print("Corrective RAG result:")
print(result)
